!function(){"use strict";const e={anamudi:{title:"Anamudi Peak (2,695m)",desc:"The highest mountain in South India and the Western Ghats, located within Eravikulam National Park. Source of the Pambar River that feeds Lakkam Falls. Trekking requires special permission from the forest department."},eravikulam:{title:"Eravikulam National Park",desc:"UNESCO World Heritage Site and home to the world's largest population of the endangered Nilgiri Tahr (~750 individuals). The park protects high-altitude shola-grassland ecosystems and is the source region for several rivers."},lakkam:{title:"Lakkam Waterfalls",desc:"A pristine high-range cascade at 2,730 metres elevation, fed by the Pambar River. Located near Marayoor in the Idukki district, surrounded by shola forests and tea estates. One of Kerala's most elevated waterfalls."},marayoor:{title:"Marayoor Village",desc:"Historic village known for natural sandalwood forests, prehistoric megalithic dolmens (muniyaras) dating back 3,000 years, and traditional sugarcane cultivation. Gateway to Lakkam Falls, located just 8 km away."},munnar:{title:"Munnar Hill Station",desc:'Popular hill station at 1,600 metres elevation famous for rolling tea estates, cool climate, and scenic beauty. Base for visiting Lakkam Falls (35 km) and other high-range attractions. Known as the "Kashmir of South India."'}};document.addEventListener("DOMContentLoaded",()=>{!function(){const a=document.querySelectorAll(".map-marker"),t=document.getElementById("map-info-title"),r=document.getElementById("map-info-desc");t&&r&&a.forEach(a=>{const n=a.dataset.point,i=()=>{const a=e[n];a&&(t.textContent=a.title,r.textContent=a.desc)};a.addEventListener("click",i),a.addEventListener("keydown",e=>{"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),i())})})}(),function(){const e=document.getElementById("lk-section-nav"),a=document.querySelectorAll(".lk-nav-link");if(!e)return;const t=Array.from(a).map(e=>({link:e,section:document.getElementById(e.getAttribute("href").replace("#",""))})).filter(e=>e.section),r=e=>{a.forEach(e=>e.classList.remove("active")),e.classList.add("active")};a.forEach(e=>e.addEventListener("click",()=>r(e)));const n=new IntersectionObserver(a=>{a.forEach(a=>{if(a.isIntersecting){const t=e.querySelector(`[href="#${a.target.id}"]`);t&&r(t)}})},{rootMargin:"-40% 0px -50% 0px"});t.forEach(e=>n.observe(e.section))}(),function(){const e=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("visible"));const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),a.unobserve(e.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>a.observe(e))}(),window.Journey&&window.Journey.registerSearchItems("frontend/lakkam-waterfalls-explorer/index.html",[{id:"lakkam-main",title:"Lakkam Waterfalls Explorer",description:"Explore Lakkam Waterfalls in Munnar, Kerala - a pristine high-range cascade at 2,730m in the Anaimalai Hills, featuring shola forests, tea estate landscapes, and rich mountain biodiversity.",link:"frontend/lakkam-waterfalls-explorer/index.html"},{id:"lakkam-structure",title:"Lakkam Waterfalls Structure",description:"Journey of the Pambar River from Anamudi Peak (2,695m) through Eravikulam National Park, Lakkam cascade, and tea estates to Chinnar Wildlife Sanctuary.",link:"frontend/lakkam-waterfalls-explorer/index.html#structure"},{id:"lakkam-ecosystem",title:"Lakkam High-Range Ecosystem",description:"Unique biodiversity of the Anaimalai Hills - shola forests, Nilgiri Tahr, endemic birds, Neelakurinji blooms, and montane grasslands around Lakkam Waterfalls.",link:"frontend/lakkam-waterfalls-explorer/index.html#ecosystem"}])})}();